<script setup>
import {ref,reactive,computed,watch,onUnmounted} from 'vue';
import {chapters,codes,requiredLessons,findLesson,lessonRoute,CURRICULUM_SOURCES} from './data/course';import {TERMS} from './data/terms';import {LEVELS,WORLD_NAMES,cleanProgress,experience,equalOutput,localDateKey,readingCount,completeLesson,DAILY_READING_TARGET} from './logic';
import Visualizer from './components/Visualizer.vue';import CodeReader from './components/CodeReader.vue';
import SiteHeader from './components/SiteHeader.vue';import ChapterDrawer from './components/ChapterDrawer.vue';
import AccountPanel from './components/AccountPanel.vue';import {useCloudProgress} from './useCloudProgress';
import LessonComments from './components/LessonComments.vue';
import TraceLab from './components/TraceLab.vue';import LessonFoundation from './components/LessonFoundation.vue';import LessonPractice from './components/LessonPractice.vue';import {TRACE_TYPES} from './traces';
const allLessons=chapters.flatMap(c=>c.lessons),ids=allLessons.map(l=>l.id),maxXp=allLessons.length*30+chapters.length*150;
const props=defineProps({progressServices:Object,commentsService:Object});
function readRoute(){const path=location.hash.slice(1)||'/';if(path==='/checkin'){history.replaceState({},'',location.pathname+location.search+'#/account');return '/account';}return path;}
const route=ref(readRoute()),query=ref(''),notice=ref('');
const {progress,storageOK,cloud}=useCloudProgress(ids,props.progressServices);
const today=ref(localDateKey());
function refreshDay(){today.value=localDateKey();}
const clockTimer=setInterval(refreshDay,60000);document.addEventListener('visibilitychange',refreshDay);
onUnmounted(()=>{clearInterval(clockTimer);document.removeEventListener('visibilitychange',refreshDay)});
const parts=computed(()=>route.value.split('/').filter(Boolean)),view=computed(()=>parts.value[0]||'home');
const drawerOpen=ref(false),hasChapterMenu=computed(()=>['learn','boss'].includes(view.value));
watch(route,()=>{drawerOpen.value=false;});
const chapter=computed(()=>chapters.find(c=>c.id===Number(parts.value[1]))||chapters[0]);
const lessonIndex=computed(()=>{const index=Number(parts.value[2]||0);return Number.isInteger(index)?Math.max(0,Math.min(chapter.value.lessons.length-1,index)):0;});
const lesson=computed(()=>chapter.value.lessons[lessonIndex.value]);const boss=computed(()=>chapter.value.boss);
const bossDemo=computed(()=>({1480:'prefix',2235:'function',1342:'reduce',704:'binary',1051:'bubble',20:'stack',1:'twoSum',78:'backtrack',104:'treeBfs',733:'flood',70:'dp',121:'stock'}[boss.value.lc]));
const xp=computed(()=>experience(progress));const level=computed(()=>{let i=LEVELS.findLastIndex(l=>xp.value>=l.min);if(i===5&&chapters.filter(clearedBoss).length<chapters.length)i=4;return {index:i,...LEVELS[i],next:LEVELS[i+1]}});
const worlds=computed(()=>WORLD_NAMES.map((name,i)=>({name,index:i,chapters:chapters.filter(c=>c.world===i)})));
const filtered=computed(()=>query.value.trim()?allLessons.filter(l=>(l.title+l.concept+l.trap).toLowerCase().includes(query.value.trim().toLowerCase())):[]);
function clearedBoss(c){return progress.bosses.includes(c.id)&&(c.id!==5||progress.bossTasks[5]===1051);}
const clearedCount=computed(()=>chapters.filter(clearedBoss).length);
const continuePath=computed(()=>{const nextLesson=allLessons.find(l=>!l.optional&&(!progress.mastery.includes(l.id)||!progress.lessons.includes(l.id)));if(nextLesson)return lessonRoute(nextLesson.id);const nextBoss=chapters.find(c=>!clearedBoss(c));return nextBoss?`/boss/${nextBoss.id}`:'/progress';});
const resumeTitle=computed(()=>{const [page,id,index]=continuePath.value.split('/').filter(Boolean),c=chapters.find(c=>c.id===Number(id));return page==='learn'?c?.lessons[Number(index)]?.title:page==='boss'?`章末闯关：${c?.boss.title}`:'课程已完成，可以从目录选择内容复习。';});
const lessonMastered=computed(()=>progress.mastery.includes(lesson.value.id));
const codeReady=computed(()=>!boss.value.codePrerequisiteChapters||boss.value.codePrerequisiteChapters.every(id=>requiredLessons(chapters.find(c=>c.id===id)).every(l=>progress.mastery.includes(l.id))));
function markMastered(id){if(!progress.mastery.includes(id)){progress.mastery.push(id);toast('本节三道练习已通过，可以记录学习并继续。');}}
function chapterReady(c){return requiredLessons(c).every(l=>progress.lessons.includes(l.id)&&progress.mastery.includes(l.id));}

const todayReadCount=computed(()=>cloud.state.user?readingCount(progress,today.value):0);
const signedToday=computed(()=>progress.checkins.includes(today.value));
function go(path){if(path==='/checkin')path='/account';location.hash=path;route.value=path;query.value='';window.scrollTo({top:0});}
function onHash(){route.value=readRoute();window.scrollTo({top:0});}window.addEventListener('hashchange',onHash);onUnmounted(()=>window.removeEventListener('hashchange',onHash));
function toast(s){notice.value=s;setTimeout(()=>notice.value='',3500)}
function complete(){
 if(cloud.state.initializing)return;
 refreshDay();const result=completeLesson(progress,lesson.value.id,today.value,!!cloud.state.user);
 if(!result.ok){toast('先通过本节的三道练习，再记录学完。');return;}
 if(result.checkedIn)toast('今日已完成4个不同小节，自动打卡成功！');
 else if(cloud.state.user)toast(result.newReading?`${result.isNew?'小节已记下，+30 XP。':'已记录今日阅读。'}今日已完成 ${result.count} 个小节${signedToday.value?'，继续加深今天的绿色。':`，再完成 ${Math.max(0,DAILY_READING_TARGET-result.count)} 个自动打卡。`}`:'本节今天已经记录过，不重复计数。');
 else toast(result.isNew?'小节已记下，+30 XP。登录后可开启每日自动打卡。':'学习记录已保存在本机。登录后可开启每日自动打卡。');
 const next=chapter.value.lessons[lessonIndex.value+1];if(next&&!next.optional)go(`/learn/${chapter.value.id}/${lessonIndex.value+1}`);else go(`/boss/${chapter.value.id}`);
}
watch(()=>cloud.state.user?.id,id=>{if(id&&view.value==='login')go('/account');});

function bookmark(){const i=progress.bookmarks.indexOf(lesson.value.id);if(i<0)progress.bookmarks.push(lesson.value.id);else progress.bookmarks.splice(i,1);}
const note=computed({get:()=>progress.notes[lesson.value.id]||'',set:v=>progress.notes[lesson.value.id]=v.slice(0,5000)});
const practice=reactive({answers:['',''],checked:[false,false],feedback:['',''],pick:-1,pickChecked:false,hints:0,solution:false});
watch([()=>chapter.value.id,()=>cloud.state.user?.id],()=>{Object.assign(practice,{answers:['',''],checked:[false,false],feedback:['',''],pick:-1,pickChecked:false,hints:0,solution:false})});
const learnedChapter=computed(()=>chapterReady(chapter.value));
const battleReady=computed(()=>learnedChapter.value&&practice.checked.every(Boolean)&&practice.pickChecked);
function checkCase(i){let output;try{output=JSON.parse(practice.answers[i]);}catch{practice.feedback[i]='请用 JSON 格式：数字直接写，真假写 true/false，数组用方括号。';practice.checked[i]=false;return;}
 const ok=equalOutput(output,boss.value.cases[i].output,boss.value.lc);practice.checked[i]=ok;practice.feedback[i]=ok?'正确。再说一说你是怎样一步步得到它的。':'还没对上。把中间状态写出来，或展开下一层提示再试。';}
function checkChoice(){practice.pickChecked=practice.pick===boss.value.correct;toast(practice.pickChecked?'思路检查通过。':'再想想关键状态和更新顺序，可以回看本章对应小节。');}
function claim(){if(!battleReady.value||clearedBoss(chapter.value))return;const rewarded=progress.bosses.includes(chapter.value.id);if(!rewarded)progress.bosses.push(chapter.value.id);progress.bossTasks[chapter.value.id]=boss.value.lc;toast(rewarded?'新版章节挑战已通过，既往奖励不重复发放。':`第 ${chapter.value.id} 章闯关通过，+150 XP！`);}

function exportProgress(){download('algo-quest-progress.json',JSON.stringify({...progress,exportedAt:new Date().toISOString()},null,2),'application/json')}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function importProgress(e){const file=e.target.files?.[0];if(!file)return;try{if(file.size>1000000)throw Error('文件过大');const targetAccount=cloud.state.user?.id||'guest',text=await file.text();if(targetAccount!==(cloud.state.user?.id||'guest')){toast('账号已切换，请在当前账号重新选择备份。');e.target.value='';return;}const p=cleanProgress(JSON.parse(text),ids);progress.lessons=[...new Set([...progress.lessons,...p.lessons])];progress.mastery=[...new Set([...progress.mastery,...p.mastery])];for(const [id,lc] of Object.entries(p.bossTasks))if(!progress.bossTasks[id]||lc===chapters.find(c=>c.id===Number(id))?.boss.lc)progress.bossTasks[id]=lc;progress.bosses=[...new Set([...progress.bosses,...p.bosses])];progress.bookmarks=[...new Set([...progress.bookmarks,...p.bookmarks])];progress.notes={...p.notes,...progress.notes};progress.checkins=[...new Set([...progress.checkins,...p.checkins])].sort();for(const [day,items] of Object.entries(p.dailyRead))progress.dailyRead[day]=[...new Set([...(progress.dailyRead[day]||[]),...items])];toast('已合并备份，保留当前进度、笔记和打卡记录。')}catch{toast('未导入：请使用本站导出的有效进度 JSON。')}e.target.value='';}
const COURSE_TERMS={...TERMS};for(const l of allLessons)for(const t of l.foundation.terms)if(!COURSE_TERMS[t.term])COURSE_TERMS[t.term]=['课程术语',t.meaning,t.example];
const glossaryQuery=ref(''),term=ref('int');const glossaryItems=computed(()=>Object.entries(COURSE_TERMS).filter(([k,v])=>(k+' '+v[1]).toLowerCase().includes(glossaryQuery.value.toLowerCase())));
const termInfo=computed(()=>COURSE_TERMS[term.value]);
const dayText='Java 基础、算法讲解与配套练习。';
</script>
<template>
<div class="app-layout" :class="{'has-chapter-menu':hasChapterMenu,'chapter-menu-open':drawerOpen}"><div class="app-surface" :inert="drawerOpen">
<div class="topline"><span>ALGO QUEST / Java 与算法入门</span><span>{{chapters.length}} 章 · {{allLessons.length}} 节 · 216 道练习</span></div>
<SiteHeader :user="cloud.state.user" :view="view" :chapter-id="chapter.id" @navigate="go"/>
<div v-if="!storageOK" class="storage-warning">当前浏览器保存功能不可用。可以继续学习，离开前请到角色记录里导出进度。</div>
<div v-if="notice" class="toast" role="status">{{notice}}</div>
<main v-if="view==='home'" class="home">
<section class="hero"><div class="hero-intro"><span class="eyebrow">十二章基础课程</span><h1>Java 与算法入门</h1><p>先学语法，再学数组、排序和常用算法。<br>每节都有操作演示、逐行代码说明和三道练习。</p><button class="primary start" @click="go(continuePath)">{{progress.lessons.length?'继续学习 →':'从第1章开始 →'}}</button><div class="hero-meta"><span>已读 {{progress.lessons.length}} / {{allLessons.length}} 节</span><span>练习通过 {{progress.mastery.length}} 节</span><span>闯关 {{clearedCount}} / {{chapters.length}}</span></div></div><div class="hero-next"><small>接下来学习</small><h2>{{resumeTitle}}</h2><p>通过本节练习后，点击“学完”保存进度。登录后，每天完成4个不同小节可自动打卡。</p></div><div class="scene" aria-hidden="true"><i class="sprite"></i><i class="ground"></i></div></section>

<section class="search-block"><div><h2>课程目录</h2><p class="muted">按章节顺序学习；标为选学的内容可以稍后再看。</p></div><label><span class="sr-only">搜索知识点</span><input v-model="query" type="search" placeholder="搜索：递归、循环、二分、栈……"/></label></section>
<div v-if="query" class="search-results"><p v-if="!filtered.length">没有找到，试试更短的词。</p><button v-for="l in filtered" :key="l.id" @click="go(lessonRoute(l.id))"><strong>{{l.title}}</strong><span>{{l.concept}}</span></button></div>
<div v-else class="world-grid"><section v-for="w in worlds" :key="w.name" class="world-card"><span class="eyebrow">第 {{w.index+1}} 部分</span><h2>{{w.name}}</h2><div class="world-route"><article v-for="c in w.chapters" :key="c.id" class="chapter-node"><button class="chapter-number" :class="{cleared:clearedBoss(c)}" @click="go('/learn/'+c.id+'/0')">{{clearedBoss(c)?'✓':String(c.id).padStart(2,'0')}}</button><div><button class="chapter-title" @click="go('/learn/'+c.id+'/0')">{{c.title}}</button><p>{{c.subtitle}}</p><small>{{c.lessons.filter(l=>progress.lessons.includes(l.id)).length}} / {{c.lessons.length}} 已读 · {{c.lessons.filter(l=>progress.mastery.includes(l.id)).length}} 节练习通过</small><button class="boss-link" @click="go('/boss/'+c.id)">⚑ {{chapterReady(c)?'已解锁':'待完成练习'}}：{{c.boss.title}} ↗</button></div></article></div></section></div>
<section class="howto"><h2>每节怎么学</h2><ol><li><b>01</b>从生活例子理解概念</li><li><b>02</b>自己操作每一步，观察变量</li><li><b>03</b>点开 Java 每行和每个词</li><li><b>04</b>完成基础、推演、应用三题</li><li><b>05</b>看题解，再独立复述一次</li></ol><p>小节首次学完 +30 XP；章末首次通关 +150 XP。答错不扣分，复习不重复计分。</p></section>
</main>
<main v-else-if="view==='learn'||view==='boss'" class="learning-shell"><aside class="course-sidebar"><button class="back-map" @click="go('/')">← 回到世界地图</button><span class="eyebrow">CHAPTER {{String(chapter.id).padStart(2,'0')}}</span><h2>{{chapter.title}}</h2><p>{{chapter.subtitle}}</p><div class="lesson-nav"><button v-for="(l,i) in chapter.lessons" :key="l.id" :class="{selected:view==='learn'&&lessonIndex===i}" @click="go('/learn/'+chapter.id+'/'+i)"><b>{{progress.mastery.includes(l.id)?'✓':i+1}}</b><span>{{l.title}}<small v-if="l.optional">选学 · 不影响基础闯关</small></span></button><button :class="{selected:view==='boss'}" @click="go('/boss/'+chapter.id)"><b>⚑</b><span>章末闯关<br><small>{{chapter.boss.title}}</small></span></button></div><div class="side-tip"><strong>本章学习</strong><p>遇到不熟悉的词，可以在生词本里查找。</p><button @click="go('/glossary')">打开生词本 ↗</button></div></aside>
<article v-if="view==='learn'" class="lesson-content" :key="lesson.id" :data-lesson="lesson.id">
  <div class="breadcrumb">{{WORLD_NAMES[chapter.world]}} / 第 {{chapter.id}} 章 / 小节 {{lessonIndex+1}} <span v-if="lesson.optional">· 选学</span></div>
  <div class="lesson-title"><div><span class="eyebrow">建议 12～20 分钟</span><h1>{{lesson.title}}</h1></div><button @click="bookmark" :aria-pressed="progress.bookmarks.includes(lesson.id)">{{progress.bookmarks.includes(lesson.id)?'★ 已收藏':'☆ 收藏'}}</button></div>
  <div v-if="lesson.prerequisiteIds.length" class="prerequisite-links"><strong>先回顾</strong><button v-for="id in lesson.prerequisiteIds" :key="id" @click="go(lessonRoute(id))">{{findLesson(id)?.title}} ↗</button></div>
  <p v-if="lesson.optional" class="optional-note">这是进阶选学。先完成本章基础内容和练习也能闯关，熟练后可再回来学习。</p>
  <section class="story"><span class="eyebrow">从熟悉的事情开始</span><p>{{lesson.story}}</p></section>
  <LessonFoundation :unit="lesson.foundation"/>
  <TraceLab v-if="TRACE_TYPES.includes(lesson.foundation.demo)" :key="lesson.id" :mode="lesson.foundation.demo" :variant="lesson.codeKey==='stairs'?'rolling':''" :plain="!lesson.showCode"/>
  <Visualizer v-else :key="lesson.id" :type="lesson.viz"/>
  <aside class="cost-note"><strong>时间和空间怎么数</strong><p>{{lesson.complexity}}</p></aside>
  <CodeReader v-if="lesson.showCode" :guide-key="lesson.codeKey" :program="lesson.code" :filename="lesson.codeKey==='entry'?'Main.java':'Solution.java'"/>
  <p v-else class="code-later">本节先把概念和操作说明白，不要求阅读尚未讲授的完整Java程序。后续对应小节会逐句拆解实现。</p>
  <section v-if="lesson.foundation.links" class="related-problems"><h2>对应的力扣练习</h2><article v-for="link in lesson.foundation.links" :key="link.lc"><a :href="link.url" target="_blank" rel="noopener">LC {{link.lc}} · {{link.name}} ↗</a><p>{{link.focus}}</p><details v-if="link.lc===912"><summary>本节已学方法的完整答案</summary><CodeReader guide-key="merge" :program="codes.merge" title="LC 912 · 归并排序完整答案"/></details></article></section>
  <LessonPractice :key="'practice-'+(cloud.state.user?.id||'guest')+'-'+lesson.id" :lesson="lesson" :mastered="lessonMastered" @mastered="markMastered"/>
  <section class="notebook"><h2>学习笔记</h2><p class="micro">写出输入、关键状态、下一步和容易错的地方。{{cloud.state.user?'笔记会自动保存，并同步到当前账号。':'游客笔记保存在当前浏览器，登录后可以选择合并。'}}</p><textarea v-model="note" maxlength="5000" placeholder="例如：a[i+1]先算下标，不会改变i；移动会覆盖旧格，value保留待插入的数。"></textarea></section>
  <div class="daily-lesson"><span>{{cloud.state.user?`今日阅读 · ${todayReadCount} 个小节${signedToday?' · 已打卡 ✓':` / ${DAILY_READING_TARGET} 个自动打卡`}`:'登录后，每天完成4个不同小节可自动打卡'}}</span><p>{{lessonMastered?'本节练习已通过，点击下方按钮记录学完。':'请先通过上面的三道练习，再点击学完。'}}{{cloud.state.user?'可跨章节累计，同一小节当天只计一次。':'游客学习记录仍保存在当前浏览器。'}}</p></div>
  <div class="lesson-actions"><button @click="go('/learn/'+chapter.id+'/'+Math.max(0,lessonIndex-1))" :disabled="lessonIndex===0">← 上一节</button><button class="primary" @click="complete" :disabled="!lessonMastered||cloud.state.initializing">{{progress.lessons.includes(lesson.id)?'记录今日阅读并继续':'我学完了 · +30 XP'}} {{chapter.lessons[lessonIndex+1]&&!chapter.lessons[lessonIndex+1].optional?'→ 下一节':'→ 章末闯关'}}</button></div>
  <LessonComments :lesson-id="lesson.id" :user="cloud.state.user" :service="props.commentsService" @login="cloud.signIn"/>
</article>
<article v-else-if="!learnedChapter" class="boss-content"><div class="breadcrumb">{{WORLD_NAMES[chapter.world]}} / 第 {{chapter.id}} 章 / BOSS CHALLENGE</div><section class="boss-section"><span class="eyebrow">BOSS LOCKED</span><h1>章末闯关尚未解锁</h1><p>完成本章基础小节及其配套练习后，即可挑战「{{boss.title}}」。</p><p>基础练习通过：{{requiredLessons(chapter).filter(l=>progress.mastery.includes(l.id)).length}} / {{requiredLessons(chapter).length}} 小节</p><button class="primary" @click="go('/learn/'+chapter.id+'/'+Math.max(0,chapter.lessons.findIndex(l=>!l.optional&&(!progress.lessons.includes(l.id)||!progress.mastery.includes(l.id)))))">继续本章学习 →</button></section></article>
<article v-else class="boss-content" :key="chapter.id" :data-chapter="chapter.id"><div class="breadcrumb">{{WORLD_NAMES[chapter.world]}} / 第 {{chapter.id}} 章 / BOSS CHALLENGE</div><div class="boss-heading"><span class="flag">⚑</span><div><span class="eyebrow">CHAPTER BOSS · LC {{boss.lc}}</span><h1>{{boss.title}}</h1><p>{{clearedBoss(chapter)?'这一章已经通关。随时回来练习。':'用这一章学到的知识，试着独立解决一次。'}}</p></div><span class="reward">首次 +150 XP</span></div>
<div v-if="cloud.state.user&&signedToday" class="daily-ready"><div><strong>今日已打卡</strong><p>继续学习可以加深今天的绿色，同一天不会重复打卡。</p></div><button @click="go('/account')">查看学习足迹 →</button></div>
<section class="boss-section"><div class="section-bar"><h2>01 / 读懂题目</h2><a :href="boss.url" target="_blank" rel="noopener">力扣原题 LC {{boss.lc}} ↗</a></div><p>{{boss.description}}</p><p class="micro">以下是重新编写的中文学习说明，原题要求以链接为准。</p><div class="prerequisite-links"><strong>本题已学前置</strong><button v-for="id in boss.review" :key="id" @click="go(lessonRoute(id))">{{findLesson(id)?.title}} ↗</button></div><div class="relation"><h3>它与这一章有什么关系？</h3><ul><li v-for="r in boss.relation">{{r}}</li></ul></div></section>
<section class="boss-section"><h2>02 / 自己走一遍</h2><p>先不用写一整段程序。根据输入，算出输出，再回答思路问题。这里检查你的结果与理解；网页不会编译 Java。</p><div class="case-grid"><article v-for="(c,i) in boss.cases" :key="i" class="test-case"><h3>情境 {{i+1}}</h3><pre>{{JSON.stringify(c.input,null,2)}}</pre><label>你的输出（JSON）<textarea v-model="practice.answers[i]" @input="practice.checked[i]=false" :placeholder="typeof c.output==='number'?'例如：3':typeof c.output==='boolean'?'例如：true':'例如：[1,2,3]'" :aria-label="`情境 ${i+1} 输出`"></textarea></label><button @click="checkCase(i)">{{practice.checked[i]?'✓ 已答对':'检查结果'}}</button><p class="case-feedback" aria-live="polite">{{practice.feedback[i]}}</p></article></div><div class="choice-question"><h3>{{boss.question}}</h3><div><button v-for="(o,i) in boss.options" :key="o" :aria-pressed="practice.pick===i" :class="{selected:practice.pick===i}" @click="practice.pick=i;practice.pickChecked=false"><b>{{'ABC'[i]}}</b>{{o}}</button></div><button @click="checkChoice" :disabled="practice.pick<0">{{practice.pickChecked?'✓ 思路检查通过':'检查思路'}}</button></div>
<div class="hint-box"><button @click="practice.hints=Math.min(boss.hints.length,practice.hints+1)" :disabled="practice.hints===boss.hints.length">{{practice.hints===boss.hints.length?'提示已全部展开':'卡住了，给我下一层提示'}} {{practice.hints}} / {{boss.hints.length}}</button><p v-for="(h,i) in boss.hints.slice(0,practice.hints)"><b>提示 {{i+1}}</b> {{h}}</p></div></section>
<section class="boss-section solution"><div class="section-bar"><h2>03 / 详细题解与完整答案</h2><button @click="practice.solution=!practice.solution">{{practice.solution?'收起题解 ↑':'展开题解 ↓'}}</button></div><p v-if="!practice.solution" class="muted">先试着说说你会保留什么状态、每次怎样改变。想清楚再来核对。</p><div v-else><h3>按这几步做</h3><ol class="solution-steps"><li v-for="(s,i) in boss.approach"><b>{{String(i+1).padStart(2,'0')}}</b><span>{{s}}</span></li></ol><TraceLab v-if="TRACE_TYPES.includes(bossDemo)" :key="'boss-'+boss.lc" :mode="bossDemo" :variant="boss.codeKey==='stairs'?'rolling':''" :plain="chapter.id===1"/><Visualizer v-else :type="bossDemo"/><h3>为什么这样做是对的？</h3><p>{{boss.proof}}</p><h3>复杂度</h3><p>{{boss.complexity}}</p><h3>这几处要特别留意</h3><ul><li v-for="p in boss.pitfalls">{{p}}</li></ul><div class="case-answer"><h3>情境的完整答案</h3><div v-for="(c,i) in boss.cases"><b>{{i+1}}.</b><code>{{JSON.stringify(c.output)}}</code></div></div><CodeReader v-if="codeReady" :guide-key="boss.codeKey" :program="boss.code" :title="'完整 Java 答案 · LC '+boss.lc"/><div v-if="!codeReady" class="code-later"><p>这一章先练自然语言步骤与累计结果。完整Java答案将在通过第2、3章基础练习后显示，避免提前要求你理解数组循环语法。</p><button @click="go(lessonRoute('2-1'))">去第2章学习Java基础 →</button></div><p class="micro">可复制到力扣对应题目的 Java 编辑区提交。Solution 是平台调用的类；树题的 TreeNode 由平台提供。本项目也附有可独立编译的答案验证文件。</p></div></section>
<section class="clear-chapter"><div><h2>{{clearedBoss(chapter)?'本章通关 ✓':'准备好结束这一章了吗？'}}</h2><p>学完 {{requiredLessons(chapter).length}} 节基础学习及练习、答对 2 个输出、通过 1 个思路问题，即可领取本章首次奖励。</p><div class="checklist"><span>{{learnedChapter?'✓':'○'}} {{requiredLessons(chapter).length}} 节基础学习与练习</span><span>{{practice.checked.every(Boolean)?'✓':'○'}} 两个输出</span><span>{{practice.pickChecked?'✓':'○'}} 思路检查</span></div></div><button class="primary" @click="claim" :disabled="!battleReady||clearedBoss(chapter)">{{clearedBoss(chapter)?'已领取奖励':'完成闯关 · +150 XP'}}</button><button v-if="!learnedChapter" @click="go('/learn/'+chapter.id+'/0')">返回本章学习</button><button v-if="clearedBoss(chapter)&&chapter.id<chapters.length" @click="go('/learn/'+(chapter.id+1)+'/0')">去下一章 →</button></section>
</article></main>
<main v-else-if="view==='account'||view==='login'" class="account-main"><AccountPanel :cloud="cloud" :progress="progress" :today="today" @continue="go(continuePath)"/></main>
<main v-else-if="view==='progress'" class="record-page"><span class="eyebrow">课程进度</span><h1>角色记录</h1><div class="record-summary"><h2>Lv.{{level.index+1}} / {{level.name}}</h2><strong>{{xp}} XP</strong><p>{{progress.lessons.length}} / {{allLessons.length}} 小节 · {{clearedCount}} / {{chapters.length}} 章通关 · {{progress.bookmarks.length}} 个收藏</p><div class="xp-track"><i :style="{width:Math.min(100,xp/maxXp*100)+'%'}"></i></div><p class="micro">全部内容最高 {{maxXp}} XP。“算法大牛”需要达到 3000 XP，且 {{chapters.length}} 章都通关。称号记录这套课程的学习进度。</p></div><div class="level-grid"><article v-for="(l,i) in LEVELS" :key="l.name" :class="{achieved:i<=level.index}"><b>Lv.{{i+1}}</b><h3>{{l.name}}</h3><small>{{l.min}} XP 起{{i===5?' ＋全章通关':''}}</small></article></div><section class="backup"><h2>把进度带走</h2><p>{{cloud.state.user?'账号进度会自动同步到云端，也可以导出JSON作为额外备份。':'游客进度保存在当前浏览器。可以登录开启云端存档，或导出JSON备份。'}}</p><button @click="exportProgress">导出进度 JSON</button><label class="file-button">导入备份<input type="file" accept=".json,application/json" @change="importProgress"/></label></section><section><h2>收藏的知识点</h2><p v-if="!progress.bookmarks.length" class="muted">遇到想再看一次的小节，可以点右上角的收藏。</p><div class="saved-lessons"><button v-for="id in progress.bookmarks" @click="go(lessonRoute(id))">☆ {{allLessons.find(l=>l.id===id)?.title}} ↗</button></div></section><section class="chapter-record"><h2>逐章进度</h2><p class="micro">旧版阅读与奖励保留；新版小节练习单独记录通过状态。</p><button v-for="c in chapters" @click="go('/learn/'+c.id+'/0')"><span>{{String(c.id).padStart(2,'0')}} / {{c.title}}</span><small>{{c.lessons.filter(l=>progress.lessons.includes(l.id)).length}} / {{c.lessons.length}} 小节 · {{clearedBoss(c)?'闯关通过':'待闯关'}}</small></button></section></main>
<main v-else-if="view==='glossary'" class="glossary-page"><span class="eyebrow">术语查询</span><h1>生词本</h1><input v-model="glossaryQuery" placeholder="搜索 int、返回值、队列……" type="search"/><div class="glossary-layout"><div class="term-list"><button v-for="[k,t] in glossaryItems" @click="term=k" :class="{selected:term===k}"><code>{{k}}</code><small>{{t[0]}}</small></button></div><aside v-if="termInfo" class="npc-dialog"><h2>{{term}}</h2><span class="eyebrow">{{termInfo[0]}}</span><p>{{termInfo[1]}}</p><pre>{{termInfo[2]}}</pre><p class="micro">具体变量名的用途，还要结合所在语句和题目一起看。</p></aside></div></main>
<main v-else class="record-page"><h1>这一页还没有路线。</h1><button @click="go('/')">回到世界地图</button></main>
<footer class="footer"><span>算法之旅 / ALGO QUEST · {{dayText}}</span><details><summary>课程参考与使用说明</summary><p>独立编写的入门讲解、图解和答案，知识组织参考 <a href="https://www.hello-algo.com/" target="_blank" rel="noopener">Hello 算法</a> 与 <a href="https://algo.itcharge.cn/" target="_blank" rel="noopener">算法通关手册</a>，语法参考 <a href="https://dev.java/learn/" target="_blank" rel="noopener">Java 官方教程</a>，可视化与即时练习的组织参考 <a href="https://visualgo.net/en/sorting/" target="_blank" rel="noopener">VisuAlgo</a> 与 <a href="https://opendsa.cs.vt.edu/" target="_blank" rel="noopener">OpenDSA</a>。本站讲解、题目与交互均重新编写。章末题保留力扣原题链接。图解为内置概念演示，网页不编译任意 Java。游客进度保存在当前浏览器；登录后可同步到账号。下载项目后也可以离线学习。</p></details></footer>
</div><ChapterDrawer v-if="hasChapterMenu" v-model:open="drawerOpen" :chapters="chapters" :chapter-id="chapter.id" :progress="progress" @navigate="go"/></div>
</template>
